// src/components/Navigation.js
import React, { useState } from "react";
import { Navbar, Nav, NavDropdown, Button, Container } from "react-bootstrap";
import { Link } from "react-router-dom";
import "./Navigation.css";

const Navigation = () => {
  // State to control dropdown hover effect
  const [showDropdown, setShowDropdown] = useState({
    aboutUs: false,
    cards: false,
    features: false,
    accounts: false,
    resources: false,
    help: false,
  });

  const handleMouseEnter = (dropdown) => {
    setShowDropdown({ ...showDropdown, [dropdown]: true });
  };

  const handleMouseLeave = (dropdown) => {
    setShowDropdown({ ...showDropdown, [dropdown]: false });
  };

  return (
    <Navbar expand="lg" variant="dark" style={{ backgroundColor: "#2d2d2d" }}>
      <Container>
        {/* Brand: Fi */}
        <Navbar.Brand as={Link} to="/" className="fw-bold fs-3" style={{ color: "#28c7b7" }}>
          Fi
        </Navbar.Brand>

        <Navbar.Toggle aria-controls="navbarNav" />
        <Navbar.Collapse id="navbarNav" className="justify-content-end">
          <Nav>
            {/* ABOUT US Dropdown */}
            <NavDropdown
              title="ABOUT US"
              id="nav-dropdown-aboutus"
              show={showDropdown.aboutUs}
              onMouseEnter={() => handleMouseEnter("aboutUs")}
              onMouseLeave={() => handleMouseLeave("aboutUs")}
            >
              <NavDropdown.Item as={Link} to="/whats-fi">What’s Fi</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/team">Team</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/careers">Careers</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/contact-us">Contact Us</NavDropdown.Item>
            </NavDropdown>

            {/* CARDS Dropdown */}
            <NavDropdown
              title="CARDS"
              id="nav-dropdown-cards"
              show={showDropdown.cards}
              onMouseEnter={() => handleMouseEnter("cards")}
              onMouseLeave={() => handleMouseLeave("cards")}
            >
              <NavDropdown.Item as={Link} to="/debit-card">Debit Card</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/credit-card">Credit Card</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/super-card">Super Card</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/fi-secured-cc">Fi-Secured CC</NavDropdown.Item>
            </NavDropdown>

            {/* FEATURES Dropdown (Updated for hover) */}
            <NavDropdown
              title="FEATURES"
              id="nav-dropdown-features"
              className="custom-dropdown"
              show={showDropdown.features}
              onMouseEnter={() => handleMouseEnter("features")}
              onMouseLeave={() => handleMouseLeave("features")}
            >
              <div className="dropdown-menu custom-menu">
                <div className="dropdown-column">
                  <span className="dropdown-header">Know your money</span>
                  <NavDropdown.Item as={Link} to="/ask-fi">ASK FI</NavDropdown.Item>
                  <NavDropdown.Item as={Link} to="/connected-accounts">CONNECTED ACCOUNTS</NavDropdown.Item>
                  <NavDropdown.Item as={Link} to="/accounts">ACCOUNTS</NavDropdown.Item>
                </div>
                <div className="dropdown-column">
                  <span className="dropdown-header">Grow your money</span>
                  <NavDropdown.Item as={Link} to="/mutual-funds">MUTUAL FUNDS</NavDropdown.Item>
                  <NavDropdown.Item as={Link} to="/us-stocks">US STOCKS</NavDropdown.Item>
                  <NavDropdown.Item as={Link} to="/us-stock-directory">US STOCK DIRECTORY</NavDropdown.Item>
                  <NavDropdown.Item as={Link} to="/jump">JUMP</NavDropdown.Item>
                  <NavDropdown.Item as={Link} to="/deposits">DEPOSITS</NavDropdown.Item>
                  <NavDropdown.Item as={Link} to="/wealth-builder">WEALTH BUILDER</NavDropdown.Item>
                </div>
                <div className="dropdown-column">
                  <span className="dropdown-header">Pay with Fi</span>
                  <NavDropdown.Item as={Link} to="/payments">PAYMENTS</NavDropdown.Item>
                </div>
                <div className="dropdown-column">
                  <span className="dropdown-header">Automate</span>
                  <NavDropdown.Item as={Link} to="/fit-rules">FIT RULES</NavDropdown.Item>
                  <span className="dropdown-header">Rewards</span>
                  <NavDropdown.Item as={Link} to="/fi-coins-offers">FI-COINS & OFFERS</NavDropdown.Item>
                  <span className="dropdown-header">Borrow</span>
                  <NavDropdown.Item as={Link} to="/instant-loan">INSTANT LOAN</NavDropdown.Item>
                </div>
              </div>
            </NavDropdown>

            {/* Other Dropdowns */}
            <NavDropdown
              title="ACCOUNTS"
              id="nav-dropdown-accounts"
              show={showDropdown.accounts}
              onMouseEnter={() => handleMouseEnter("accounts")}
              onMouseLeave={() => handleMouseLeave("accounts")}
            >
              <NavDropdown.Item as={Link} to="/savings-account">Savings Account</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/for-companies">For Companies</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/for-individuals">For Individuals</NavDropdown.Item>
            </NavDropdown>

            <NavDropdown
              title="RESOURCES"
              id="nav-dropdown-resources"
              show={showDropdown.resources}
              onMouseEnter={() => handleMouseEnter("resources")}
              onMouseLeave={() => handleMouseLeave("resources")}
            >
              <NavDropdown.Item as={Link} to="/guides">Guides</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/calculators">Calculators</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/blogs">Blogs</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/loan-calculator">Loan Calculator</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/best-budget-directory">Best Budget Directory</NavDropdown.Item>
            </NavDropdown>

            <NavDropdown
              title="HELP"
              id="nav-dropdown-help"
              show={showDropdown.help}
              onMouseEnter={() => handleMouseEnter("help")}
              onMouseLeave={() => handleMouseLeave("help")}
            >
              <NavDropdown.Item as={Link} to="/faqs">FAQs</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/general-inquiries">General Inquiries</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/grievance-redressal">Grievance Redressal</NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/move-your-offices">Move Your Offices</NavDropdown.Item>
            </NavDropdown>

            {/* DOWNLOAD FI Button */}
            <Button variant="outline-light" className="ms-3">DOWNLOAD FI</Button>
          </Nav>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
};

export default Navigation;
